<div class="heading-actions">@foreach(['pass'=>'Passed','return'=>'Returned','cancel'=>'Cancelled'] as $action=>$label) @can('cheques.'.$action) @if(($action==='cancel' && $cheque->status==='PENDING') || ($action!=='cancel' && ($cheque->action_available || auth()->user()->hasPermission('cheques.override_action_date'))))<button class="btn {{ $action==='pass'?'primary':'secondary' }}" type="button" onclick="document.getElementById('cheque-{{ $action }}-{{ $cheque->id }}').showModal()">Mark {{ $label }}</button><dialog id="cheque-{{ $action }}-{{ $cheque->id }}" class="payment-dialog"><div class="modal-heading"><h2>Mark cheque {{ $label }}?</h2></div><form class="modal-body" method="POST" action="{{ route('cheques.action',[$cheque,$action]) }}">@csrf<input type="hidden" name="confirmed" value="1"><p>#{{ $cheque->cheque_number }} · {{ \App\Support\Money::display($cheque->amount) }} · {{ $cheque->cheque_date->format('d/m/Y') }} · {{ $cheque->parties }}</p><p>{{ $action==='pass'?'This will settle the cheque hold.':($cheque->type==='THIRD_PARTY'?'This will remove both Holds and restore Customer Due and Supplier Due.':'This will remove Hold and restore the amount to Due.') }}</p>@if($action!=='pass')<label class="field">Reason<input name="reason" maxlength="255" required value="{{ $action==='return'?\App\Support\Cheques::setting('cheque_default_return_reason'):'' }}"></label>@endif<label class="field">Notes<input name="notes" maxlength="2000"></label><div class="heading-actions"><button type="button" class="btn secondary" onclick="this.closest('dialog').close()">Cancel</button><button class="btn primary">Confirm {{ $label }}</button></div></form></dialog>@endif @endcan @endforeach</div>
